package main

import (
	"bytes"
	"go/format"
	"os"
	"path/filepath"
	"strconv"
	"testing"
)

// dct64SparseHeader is the fixed head of dct64_lanes4_sparse_gosimd.go.
const dct64SparseHeader = `// SPDX-License-Identifier: BSD-2-Clause
//
// See LICENSE for the BSD-2-Clause grant and NOTICE for the AOM attribution.

// Code generated by tools/itxzero from dct64_lanes4_gosimd.go; DO NOT EDIT.

//go:build goexperiment.simd && (amd64 || arm64) && !purego

package transform

import "simd/archsimd"

`

// TestDCT64SparseUpToDate regenerates the DCT64 Low8/16/32 kernels from
// dct64_lanes4_gosimd.go and compares them with the checked-in file.
func TestDCT64SparseUpToDate(t *testing.T) {
	dir := filepath.Join("..", "..", "internal", "av1", "transform")
	src := filepath.Join(dir, "dct64_lanes4_gosimd.go")
	var b bytes.Buffer
	b.WriteString(dct64SparseHeader)
	for _, w := range []string{"Narrow", "Wide"} {
		for _, n := range []int{8, 16, 32} {
			b.WriteString(derive(src, "inverseDCT64Lanes4"+w, n, "inverseDCT64Lanes4"+w+"Low"+strconv.Itoa(n)))
		}
	}
	want, err := format.Source(b.Bytes())
	if err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(filepath.Join(dir, "dct64_lanes4_sparse_gosimd.go"))
	if err != nil {
		t.Fatal(err)
	}
	// A Windows checkout with core.autocrlf rewrites the file to CRLF; the
	// generator (gofmt) always emits LF, so compare content, not line endings.
	got = bytes.ReplaceAll(got, []byte("\r\n"), []byte("\n"))
	if !bytes.Equal(got, want) {
		t.Fatal("dct64_lanes4_sparse_gosimd.go is stale; regenerate it with tools/itxzero (header + Narrow/Wide x Low8/16/32, gofmt)")
	}
}
